#!/bin/bash
# Leaf1: fabric underlay. Generated by Ansible - do not edit by hand.
set -e
nv set system hostname leaf1
nv set interface lo ip address 10.10.10.1/32
nv set interface swp1,swp2,swp3,swp4
nv set router bgp autonomous-system 65101
nv set router bgp router-id 10.10.10.1
nv set vrf default router bgp neighbor swp1 remote-as external
nv set vrf default router bgp neighbor swp2 remote-as external
nv set vrf default router bgp neighbor swp3 remote-as external
nv set vrf default router bgp neighbor swp4 remote-as external
nv set vrf default router bgp address-family ipv4-unicast network 10.10.10.1/32
# BFD: declare a fabric neighbor dead after 3 missed hellos 300 ms apart,
# instead of waiting for the BGP hold timer
nv set router bfd state enabled
nv set router bfd profile FABRIC detect-multiplier 3
nv set router bfd profile FABRIC min-tx-interval 300
nv set router bfd profile FABRIC min-rx-interval 300
nv set vrf default router bgp neighbor swp1 bfd profile FABRIC
nv set vrf default router bgp neighbor swp2 bfd profile FABRIC
nv set vrf default router bgp neighbor swp3 bfd profile FABRIC
nv set vrf default router bgp neighbor swp4 bfd profile FABRIC
# Server-facing ports: 10.<rail>.<server>.0/30, leaf side is .1
nv set interface swp32 ip address 10.1.1.1/30
nv set interface swp31 ip address 10.1.2.1/30
nv set interface swp30 ip address 10.1.3.1/30
nv set interface swp29 ip address 10.1.4.1/30
nv set vrf default router bgp address-family ipv4-unicast redistribute connected
nv config apply -y
nv config save
